24	+package com.better.alarm.model;
25	+
26	+import java.util.Collections;
27	+import java.util.HashSet;
28	+import java.util.LinkedList;
29	+import java.util.List;
30	+import java.util.Set;
31	+
32	+import android.content.ContentResolver;
33	+import android.content.ContentUris;
34	+import android.content.ContentValues;
35	+import android.content.Context;
36	+import android.content.Intent;
37	+import android.database.Cursor;
38	+import android.net.Uri;
39	+import android.util.Log;
40	+
41	+import com.better.alarm.model.Alarm.DaysOfWeek;
42	+
43	+/**
44	+ * The Alarms implements application domain logic
45	+ */
46	+public class Alarms implements IAlarmsManager {
47	+    private static final String TAG = "Alarms";
48	+    private static final boolean DBG = true;
49	+
50	+    private Context mContext;
51	+    private Set<IAlarmsManager.OnAlarmListChangedListener> mAlarmListChangedListeners;
52	+
53	+    private ContentResolver mContentResolver;
54	+    private Set<Alarm> set;
55	+
56	+    Alarms(Context context) {
57	+        mContext = context;
58	+        mAlarmListChangedListeners = new HashSet<IAlarmsManager.OnAlarmListChangedListener>();
59	+        mContentResolver = mContext.getContentResolver();
60	+        set = new HashSet<Alarm>();
61	+
62	+        final Cursor cursor = mContentResolver.query(Alarm.Columns.CONTENT_URI, Alarm.Columns.ALARM_QUERY_COLUMNS,
63	+                null, null, Alarm.Columns.DEFAULT_SORT_ORDER);
64	+        try {
65	+            if (cursor.moveToFirst()) {
66	+                do {
67	+                    final Alarm a = new Alarm(cursor);
68	+                    set.add(a);
69	+                } while (cursor.moveToNext());
70	+            }
71	+        } finally {
72	+            cursor.close();
73	+        }
74	+        if (DBG) {
75	+            Log.d(TAG, "Alarms:");
76	+            for (Alarm alarm : set) {
77	+                Log.d(TAG, alarm.toString());
78	+            }
79	+        }
80	+    }
81	+
82	+    @Override
83	+    public int createNewAlarm() {
84	+        Alarm alarm = new Alarm();
85	+        Uri uri = mContentResolver.insert(Alarm.Columns.CONTENT_URI, alarm.createContentValues());
86	+        alarm.setId((int) ContentUris.parseId(uri));
87	+        set.add(alarm);
88	+        // new alarm is not enabled, no need to check if it can fire. It can't
89	+        notifyAlarmListChangedListeners();
90	+        return alarm.getId();
91	+    }
92	+
93	+    @Override
94	+    public void changeAlarm(int id, boolean enabled, int hour, int minute, DaysOfWeek daysOfWeek, boolean vibrate,
95	+            String label, Uri alert, boolean preAlarm) {
96	+        Alarm alarm = getAlarm(id);
97	+        alarm.setEnabled(enabled);
98	+        alarm.setHour(hour);
99	+        alarm.setMinutes(minute);
100	+        alarm.setDaysOfWeek(daysOfWeek);
101	+        alarm.setVibrate(vibrate);
102	+        alarm.setLabel(label);
103	+        alarm.setAlert(alert);
104	+        alarm.setPrealarm(preAlarm);
105	+        changeAlarm(alarm);
106	+    }
107	+
108	+    @Override
109	+    public void delete(int alarmId) {
110	+        Alarm alarm = getAlarm(alarmId);
111	+        set.remove(alarm);
112	+        Uri uri = ContentUris.withAppendedId(Alarm.Columns.CONTENT_URI, alarmId);
113	+        mContentResolver.delete(uri, "", null);
114	+
115	+        broadcastAlarmState(getAlarm(alarmId), Intents.ALARM_DISMISS_ACTION);
116	+        notifyAlarmListChangedListeners();
117	+
118	+        setNextAlert();
119	+    }
120	+
121	+    @Override
122	+    public List<Alarm> getAlarmsList() {
123	+        List<Alarm> alarms = new LinkedList<Alarm>(set);
124	+        return alarms;
125	+    }
126	+
127	+    void onAlarmFired(Alarm alarm) {
128	+        broadcastAlarmState(alarm, Intents.ALARM_ALERT_ACTION);
129	+
130	+        // Disable this alarm if it does not repeat.
131	+        if (!alarm.getDaysOfWeek().isRepeatSet()) {
132	+            enable(alarm.getId(), false);
133	+        } else {
134	+            setNextAlert();
135	+        }
136	+    }
137	+
138	+    void onAlarmSnoozedFired(Alarm alarm) {
139	+        // TODO
140	+    }
141	+
142	+    void onAlarmSoundExpired(Alarm alarm) {
143	+        // TODO
144	+    }
145	+
146	+    @Override
147	+    public Alarm getAlarm(int alarmId) {
148	+        for (Alarm alarm : set) {
149	+            if (alarm.getId() == alarmId) {
150	+                return alarm;
151	+            }
152	+        }
153	+        return null;
154	+    }
155	+
156	+    private int changeAlarm(Alarm alarm) {
157	+        // first add to the DB
158	+        ContentValues values = alarm.createContentValues();
159	+
160	+        // this is an existing alarm
161	+        mContentResolver.update(ContentUris.withAppendedId(Alarm.Columns.CONTENT_URI, alarm.getId()), values, null,
162	+                null);
163	+        set.remove(alarm);
164	+        set.add(alarm);
165	+
166	+        if (alarm.isEnabled()) {
167	+            // Disable the snooze if we just changed the snoozed alarm. This
168	+            // only does work if the snoozed alarm is the same as the given
169	+            // alarm.
170	+            // TODO: disableSnoozeAlert should have a better name.
171	+
172	+            // Disable the snooze if this alarm fires before the snoozed alarm.
173	+            // This works on every alarm since the user most likely intends to
174	+            // have the modified alarm fire next.
175	+            // clearSnoozeIfNeeded(timeInMillis);
176	+        }
177	+        setNextAlert();
178	+        notifyAlarmListChangedListeners();
179	+        return alarm.getId();
180	+    }
181	+
182	+    /**
183	+     * A convenience method to enable or disable an alarm.
184	+     * 
185	+     * @param id
186	+     *            corresponds to the _id column
187	+     * @param enabled
188	+     *            corresponds to the ENABLED column
189	+     */
190	+    @Override
191	+    public void enable(int id, boolean enable) {
192	+        Alarm alarm = getAlarm(id);
193	+        alarm.setEnabled(enable);
194	+        changeAlarm(alarm);
195	+    }
196	+
197	+    @Override
198	+    public void snooze(Alarm alarm) {
199	+        // TODO
200	+    }
201	+
202	+    @Override
203	+    public void dismiss(Alarm alarm) {
204	+        broadcastAlarmState(alarm, Intents.ALARM_DISMISS_ACTION);
205	+        setNextAlert();
206	+        // TODO
207	+    }
208	+
209	+    private Alarm calculateNextAlert() {
210	+        Alarm alarm = null;
211	+
212	+        if (getAlarmsList().isEmpty()) {
213	+            if (DBG) Log.d(TAG, "no alarms");
214	+        } else {
215	+            alarm = Collections.min(getAlarmsList());
216	+            if (!alarm.isEnabled()) {
217	+                alarm = null;
218	+                if (DBG) Log.d(TAG, "no alarms");
219	+            } else {
220	+                if (DBG) Log.d(TAG, "next: " + alarm.toString());
221	+            }
222	+        }
223	+        return alarm;
224	+    }
225	+
226	+    /**
227	+     * Disables non-repeating alarms that have passed. Called at boot.
228	+     */
229	+    void disableExpiredAlarms() {
230	+        long now = System.currentTimeMillis();
231	+        for (Alarm alarm : set) {
232	+            if (!alarm.isEnabled() && alarm.getTimeInMillis() != 0 && alarm.getTimeInMillis() < now) {
233	+                enable(alarm.getId(), false);
234	+            }
235	+        }
236	+    }
237	+
238	+    /**
239	+     * Called at system startup, on time/timezone change, and whenever the user
240	+     * changes alarm settings. Activates snooze if set, otherwise loads all
241	+     * alarms, activates next alert.
242	+     */
243	+    void setNextAlert() {
244	+        final Alarm alarm = calculateNextAlert();
245	+        if (alarm != null) {
246	+            AlarmReceiver.setUpRTCAlarm(mContext, alarm, alarm.getTimeInMillis());
247	+            broadcastAlarmState(alarm, Intents.ACTION_ALARM_SCHEDULED);
248	+        } else {
249	+            AlarmReceiver.removeRTCAlarm(mContext);
250	+            broadcastAlarmState(alarm, Intents.ACTION_ALARMS_UNSCHEDULED);
251	+        }
252	+    }
253	+
254	+    private void broadcastAlarmState(Alarm alarm, String action) {
255	+        Intent intent = new Intent(action);
256	+        intent.putExtra(Intents.EXTRA_ID, alarm == null ? -1 : alarm.getId());
257	+        mContext.sendBroadcast(intent);
258	+    }
259	+
260	+    @Override
261	+    public void registerOnAlarmListChangedListener(OnAlarmListChangedListener listener) {
262	+        mAlarmListChangedListeners.add(listener);
263	+        notifyAlarmListChangedListeners();
264	+    }
265	+
266	+    @Override
267	+    public void unRegisterOnAlarmListChangedListener(OnAlarmListChangedListener listener) {
268	+        mAlarmListChangedListeners.remove(listener);
269	+    }
270	+
271	+    private void notifyAlarmListChangedListeners() {
272	+        for (OnAlarmListChangedListener listener : mAlarmListChangedListeners) {
273	+            listener.onAlarmListChanged(getAlarmsList());
274	+        }
275	+    }
276	+}
